-- Read-only canonical selector QA; all authority changes rollback, no new users.
begin;
set local statement_timeout='90s';
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999999902',true);
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end $$;
create function pg_temp.expect_error(query text,code text,label text) returns void language plpgsql as $$begin begin execute query;exception when others then if sqlstate=code then raise notice 'PASS %',label;return;end if;raise exception 'FAIL % expected % got %: %',label,code,sqlstate,sqlerrm;end;raise exception 'FAIL % did not reject',label;end $$;
do $$declare org uuid:='99999999-9999-4999-8999-999999999901';project uuid:='99999999-9999-4999-8999-999999999974';eng uuid:='99999999-9999-4999-8999-999999999975';campaign uuid:='99999999-9999-4999-8999-999999997172';j jsonb;begin
 j:=public.list_project_campaign_planning_contexts(org,project,eng,null,'',0,1,0,1);
 perform pg_temp.check_true(j->>'organization_id'=org::text and j->>'engagement_id'=eng::text and jsonb_array_length(j->'items')<=1 and jsonb_array_length(j->'services')<=1 and (j->>'total')::int>=1 and j->>'can_write'='true','Campaign and independent service selectors bounded in exact scope');
 j:=public.list_project_campaign_planning_contexts(org,project,eng,campaign,'',0,1);
 perform pg_temp.check_true(j#>>'{items,0,id}'='99999999-9999-4999-8999-999999997173' and j->>'campaign_id'=campaign::text,'Exact immutable plan version offered without automatic selection');
 j:=public.list_project_campaign_planning_contexts(org,project,eng,null,'no-such-selector',0,1);
 perform pg_temp.check_true(j->>'matching'='0' and j->'items'='[]'::jsonb and (j->>'total')::int>=1,'Empty filtered campaign results retain true independent totals');
 j:=public.list_project_campaign_planning_contexts(org,project,eng,campaign,'',10000,1,10000,1);
 perform pg_temp.check_true(j->'items'='[]'::jsonb and j->'services'='[]'::jsonb and j->>'has_more'='false' and j->>'services_has_more'='false','Independent offset boundaries return bounded empty pages');
 j:=public.list_project_campaign_source_candidates(org,project,eng,'artifact_version','',0,1);
 perform pg_temp.check_true(jsonb_array_length(j->'items')=1 and j#>>'{items,0,available}'='true' and j#>>'{items,0,source,approval_state}'='approved','Exact approved source descriptor rechecked on bounded read');
 perform pg_temp.check_true(not (j#>'{items,0,source}') ? 'content' and not (j#>'{items,0,source}') ? 'storage_path','Source selector returns safe metadata without bytes or Storage paths');
 j:=public.list_project_campaign_source_candidates(org,project,eng,'artifact_version','no-such-selector',0,1);
 perform pg_temp.check_true(j->>'matching'='0' and j->'items'='[]'::jsonb and (j->>'total')::int>=1,'Source title filter preserves available candidate total');
 j:=public.list_project_campaign_source_candidates(org,project,eng,'deliverable_version','no-such-selector',0,1);
 perform pg_temp.check_true(j->'items'='[]'::jsonb and j->>'source_kind'='deliverable_version','Canonical file/version selector executes without provider or Storage read');
 j:=public.list_project_campaign_contribution_candidates(org,project,eng,'project_task','',0,1);
 perform pg_temp.check_true(jsonb_array_length(j->'items')<=1 and j->>'kind'='project_task','Project Tasks stay separate and bounded');
 j:=public.list_project_campaign_contribution_candidates(org,project,eng,'engagement_work_item','',0,1);
 perform pg_temp.check_true(jsonb_array_length(j->'items')=1 and j->>'kind'='engagement_work_item' and (j#>'{items,0}') ? 'assignee_id' and (j#>'{items,0}') ? 'row_version','Work Items use current canonical assignee/deadline/version');
 perform pg_temp.expect_error(format('select public.list_project_campaign_planning_contexts(%L,%L,%L,%L)',org,project,eng,'99999999-9999-4999-8999-999999997299'),'42501','Foreign or missing exact campaign rejected');
 perform pg_temp.expect_error(format('select public.list_project_campaign_planning_contexts(%L,%L,%L)',org,project,'99999999-9999-4999-8999-999999997299'),'42501','Foreign or missing engagement rejected');
 perform pg_temp.expect_error(format('select public.list_project_campaign_planning_contexts(%L,%L,%L,null,null)',org,project,eng),'22023','Null search rejected');
 perform pg_temp.expect_error(format('select public.list_project_campaign_planning_contexts(%L,%L,%L,null,%L,0,51)',org,project,eng,''),'22023','Unbounded result limit rejected');
 perform pg_temp.expect_error(format('select public.list_project_campaign_planning_contexts(%L,%L,%L,null,%L,-1)',org,project,eng,''),'22023','Negative offset rejected');
 perform pg_temp.expect_error(format('select public.list_project_campaign_planning_contexts(%L,%L,%L,null,%L,0,25,0,51)',org,project,eng,''),'22023','Unbounded independent service limit rejected');
 perform pg_temp.expect_error(format('select public.list_project_campaign_source_candidates(%L,%L,%L,%L)',org,project,eng,'latest'),'22023','Implicit latest source rejected');
 perform pg_temp.expect_error(format('select public.list_project_campaign_contribution_candidates(%L,%L,%L,%L)',org,project,eng,'combined'),'22023','Mixed assignment category rejected');
 update public.engagement_services set status='on_hold' where id='99999999-9999-4999-8999-999999997171';
 j:=public.list_project_campaign_planning_contexts(org,project,eng,campaign);
 perform pg_temp.check_true(not exists(select 1 from jsonb_array_elements(j->'services') s where s->>'id'='99999999-9999-4999-8999-999999997171'),'Withdrawn service excluded immediately without plan mutation');
 update public.projects set archived_at=now() where id=project;
 j:=public.list_project_campaign_planning_contexts(org,project,eng,campaign);
 perform pg_temp.check_true(j->>'project_archived'='true' and j->>'can_write'='false' and jsonb_array_length(j->'items')>0,'Archived project retains bounded readable exact plan history');
end $$;
set local role authenticated;
select pg_temp.check_true(public.list_project_campaign_source_candidates('99999999-9999-4999-8999-999999999901','99999999-9999-4999-8999-999999999974','99999999-9999-4999-8999-999999999975','artifact_version')->>'source_kind'='artifact_version','Actual authenticated role can use bounded selector');
select pg_temp.expect_error('select private.campaign_lookup_scope(''99999999-9999-4999-8999-999999999901'',''99999999-9999-4999-8999-999999999974'',''99999999-9999-4999-8999-999999999975'','''',0,25)','42501','Authenticated cannot invoke private scope helper');
reset role;
select set_config('request.jwt.claim.sub','99999999-9999-4999-8999-999999997299',true);
select pg_temp.expect_error('select public.list_project_campaign_contribution_candidates(''99999999-9999-4999-8999-999999999901'',''99999999-9999-4999-8999-999999999974'',''99999999-9999-4999-8999-999999999975'',''engagement_work_item'')','42501','Unknown actor cannot read canonical work choices');
select pg_temp.check_true(not has_function_privilege('anon','public.list_project_campaign_source_candidates(uuid,uuid,uuid,text,text,integer,integer)','execute') and not has_function_privilege('service_role','public.list_project_campaign_source_candidates(uuid,uuid,uuid,text,text,integer,integer)','execute'),'Anon and service-role lookup bypass closed');
rollback;
